using Microsoft.EntityFrameworkCore;
using SysAdminAssistant.Core;
namespace SysAdminAssistant.Infrastructure;
public static class MailUpdateStore
{
 public static async Task SeedAsync(AssistantDb db,CancellationToken token){foreach(var p in await db.Profiles.Where(p=>p.UpdateDictionaryVersion==0).ToArrayAsync(token))MailUpdates.Defaults(p);await db.SaveChangesAsync(token);}
 public static async Task SyncAsync(AssistantDb db,ReportEvent report,CancellationToken token){
 // Rebinding the source must withdraw a notice from the former device without erasing acknowledgements.
 if(report.Id>0){var marker="\"ReportId\":"+report.Id+",";foreach(var old in await db.Devices.Where(d=>d.MailUpdatesJson.Contains(marker)).ToArrayAsync(token)){var history=MailUpdates.Parse(old.MailUpdatesJson);bool changed=false;foreach(var item in history.Where(x=>x.ReportId==report.Id)){if(report.MailCategory=="Update"&&!report.IsPending&&report.DeviceId==old.Id&&report.UpdateKey==item.Key)continue;var candidates=await db.Reports.Where(e=>e.Id!=report.Id&&e.DeviceId==old.Id&&e.UpdateKey==item.Key&&e.MailCategory=="Update"&&!e.IsPending).ToArrayAsync(token);var other=candidates.Where(e=>e.DeviceId==old.Id&&e.UpdateKey==item.Key&&!e.IsPending).OrderByDescending(e=>e.ReceivedAt).FirstOrDefault();if(other==null)item.Withdrawn=true;else{item.ReportId=other.Id;item.LastReceived=other.ReceivedAt;}changed=true;}if(changed)old.MailUpdatesJson=MailUpdates.Serialize(history);}}
if(report.MailCategory!="Update"||report.DeviceId==null||report.IsPending)return;var device=await db.Devices.SingleAsync(d=>d.Id==report.DeviceId,token);var rows=MailUpdates.Parse(device.MailUpdatesJson).ToList();var row=rows.FirstOrDefault(x=>x.Key==report.UpdateKey);if(row==null){if(rows.Count>=1000){report.IsPending=true;report.Issue="Достигнут лимит истории обновлений устройства (1000 версий)";return;}rows.Add(row=new(){Key=report.UpdateKey,Product=report.UpdateProduct,Version=report.UpdateVersion,FirstReceived=report.ReceivedAt,LastReceived=report.ReceivedAt});}row.Withdrawn=false;if(report.ReceivedAt>=row.LastReceived){row.LastReceived=report.ReceivedAt;row.ReportId=report.Id;}if(report.ReceivedAt<row.FirstReceived)row.FirstReceived=report.ReceivedAt;device.MailUpdatesJson=MailUpdates.Serialize(rows);}
 public static async Task<MailUpdatesView> ViewAsync(AssistantDb db,int id,CancellationToken token){var d=await db.Devices.AsNoTracking().SingleAsync(d=>d.Id==id,token);return new(id,ReportStore.Digest(d.MailUpdatesJson),MailUpdates.Parse(d.MailUpdatesJson).OrderBy(x=>x.InstalledUtc!=null).ThenByDescending(x=>x.LastReceived).ToArray(),d.OsUpdatesJson==""?null:OsUpdateStatus.Parse(d.OsUpdatesJson));}
 public static async Task ConfirmAsync(AssistantDb db,MailUpdateConfirm request,string actor,CancellationToken token){var d=await db.Devices.SingleAsync(d=>d.Id==request.DeviceId,token);if(ReportStore.Digest(d.MailUpdatesJson)!=request.ExpectedHash)throw new InvalidOperationException(global::SysAdminAssistant.Core.ProductText.Get("Список обновлений изменился; обновите окно"));var rows=MailUpdates.Parse(d.MailUpdatesJson);var item=rows.Single(x=>x.Key==request.Key);item.InstalledUtc=DateTime.UtcNow;item.ConfirmedBy=actor;d.MailUpdatesJson=MailUpdates.Serialize(rows);await db.SaveChangesAsync(token);}
 public static void Capture(NetworkState state,IEnumerable<Device> devices)=>UpdateNotifications.Suppress(state);
}
